DO \$\$ DECLARE emp1_id uuid := gen_random_uuid(); emp2_id uuid := gen_random_uuid(); team_c_id uuid := '0c8f3af9-4b18-431f-bd72-8ba20f610417'; serveur_id uuid := 'f7cd667d-b520-40e1-91a5-5488ed2af07f'; caissier_id uuid := '0949f8f1-ca1f-47f1-a02d-c496d6df3bd8'; BEGIN INSERT INTO employees (id_employee, employee_code, name, lastname, active_status) VALUES (emp1_id, 'EMP-TEST-1', 'Alice', 'Dupont', 1), (emp2_id, 'EMP-TEST-2', 'Bob', 'Martin', 1); INSERT INTO employees_job (id_emp_job, assignment_date, id_employee, id_job_title, status) VALUES (gen_random_uuid(), CURRENT_DATE, emp1_id, serveur_id, 1), (gen_random_uuid(), CURRENT_DATE, emp2_id, caissier_id, 1); DELETE FROM employee_team WHERE id_team = team_c_id; INSERT INTO employee_team (id_employee_team, id_team, id_employee) VALUES (gen_random_uuid(), team_c_id, emp1_id), (gen_random_uuid(), team_c_id, emp2_id); END \$\$;